public sealed class SecureLogger(ILogSink sink, ReadOnlyMemory<byte> key, ChainState chain) : ILogger {
    public IDisposable? BeginScope<TState>(TState s) where TState : notnull => null;
    public bool IsEnabled(LogLevel l) => l >= LogLevel.Information;
    public void Log<TState>(LogLevel l, EventId id, TState state, Exception? ex, Func<TState, Exception?, string> fmt) {
        lock (chain) {                                          // one chain, many loggers
            var body = Canonicalise(l, id, state, ex, fmt);      // fields are data, never format
            var tag = HMACSHA256.HashData(key.Span, [.. chain.Prev, .. chain.SeqBytes(), .. body]);
            sink.Append(chain.Seq, tag, body);                   // append-only, fsync per policy
            chain.Advance(tag);
        }
    }
}
